"use client";

import { motion, type Variants } from "framer-motion";
import { MapPin, GraduationCap, Heart, Globe } from "lucide-react";
import { personalInfo, aboutInfo } from "@/lib/portfolio-data";
import { SectionHeading } from "@/components/ui/section-heading";
import { Button } from "@/components/ui/button";

const containerVariants: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.1, delayChildren: 0.1 },
  },
};

const itemVariants: Variants = {
  hidden: { opacity: 0, y: 24 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.6, ease: [0.33, 1, 0.68, 1] },
  },
};

export function AboutSection() {
  const handleScroll = (href: string) => {
    const el = document.querySelector(href);
    el?.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <section id="about" className="relative px-6">
      <div className="mx-auto max-w-[var(--container-max)] px-6">
        <SectionHeading
          title={aboutInfo.title}
          subtitle={aboutInfo.subtitle}
        />

        <motion.div
          variants={containerVariants}
          className="grid lg:grid-cols-2 gap-12 items-center pt-8"
        >
          {/* Left: Profile Content */}
          <motion.div variants={itemVariants} className="flex flex-col items-start">
            <p className="mb-4 text-sm font-medium tracking-[0.15em] text-primary uppercase">
              {aboutInfo.title}
            </p>
            <h2 className="text-foreground font-extrabold tracking-tight">
              {personalInfo.name}
            </h2>
            <p className="mt-4 text-foreground-muted leading-relaxed">
              {personalInfo.bio}
            </p>

            {/* Location & Availability */}
            <div className="mt-6 flex items-center gap-2 text-xs text-foreground-subtle">
              <MapPin size={14} />
              <span>{personalInfo.location}</span>
            </div>

            <div className="mt-3 inline-flex items-center gap-2 rounded-full border border-border bg-surface px-3 py-1.5 text-xs font-medium">
              <span className="relative flex h-2 w-2">
                <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-success opacity-75" />
                <span className="relative inline-flex h-2 w-2 rounded-full bg-success" />
              </span>
              <span>{personalInfo.availabilityText}</span>
            </div>

            {/* Interests */}
            <div className="mt-6 grid grid-cols-2 gap-2">
              {aboutInfo.interests.map((interest, i) => (
                <Button
                  key={i}
                  variant="ghost"
                  size="sm"
                  className="flex items-center gap-1.5 rounded-full border border-border px-2.5 py-1.5 text-xs font-medium text-foreground"
                >
                  {interest}
                </Button>
              ))}
            </div>

            {/* Education */}
            <div className="mt-8">
              <h3 className="text-sm font-medium text-foreground mb-3">
                {aboutInfo.education.institution}
              </h3>
              <p className="text-xs text-foreground-muted">
                {aboutInfo.education.major} — {aboutInfo.education.period}
              </p>
            </div>
          </motion.div>

          {/* Right: Highlights / Stats */}
          <motion.div
            variants={itemVariants}
            className="grid grid-cols-2 gap-4 pt-2"
          >
            {aboutInfo.highlights.map((highlight, i) => (
              <div
                key={i}
                className="flex items-start gap-3 rounded-[var(--radius-md)] border border-border bg-surface p-4"
              >
                <div className="flex-shrink-0">
                  <Heart size={18} className="text-primary" />
                </div>
                <div>
                  <p className="text-sm font-medium text-foreground">{highlight.title}</p>
                  <p className="text-xs text-foreground-muted">{highlight.description}</p>
                </div>
              </div>
            ))}
          </motion.div>
        </motion.div>
      </div>
    </section>
  );
}